function SV(a) {
  return a
    .map(function (s) {
      return (
        '<article class="svc"><h3>' +
        s[0] +
        "</h3>" +
        L(s[2] || s[1]) +
        "</article>"
      );
    })
    .join("");
}
function PR(a) {
  return a
    .map(function (p) {
      return (
        '<article class="proj"><div class="body"><div class="txt"><span class="demo">' +
        (p[8] || "Portfolio demonstration") +
        "</span><h3>" +
        p[0] +
        "</h3><p>" +
        p[1] +
        "</p><h4>OBJECTIVE</h4><p>" +
        p[2] +
        "</p><h4>TOOLS USED</h4><p>" +
        p[3].join(", ") +
        "</p><h4>TASKS PERFORMED</h4>" +
        L(p[4]) +
        "<h4>DELIVERABLES</h4>" +
        L(p[5]) +
        "<h4>SKILLS DEMONSTRATED</h4>" +
        L(p[6]) +
        '</div><div class="smp"><h4>VISUAL EVIDENCE</h4><div class="samples">' +
        p[7]
          .map(function (k) {
            return (
              '<div class="sample" data-name="' +
              (CAP[k] || k) +
              '" data-key="' +
              k +
              '" data-h="220"></div>'
            );
          })
          .join("") +
        "</div></div></div></article>"
      );
    })
    .join("");
}
